package com.daniil.wristlens.wear;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import androidx.wear.remote.interactions.RemoteActivityHelper;import com.google.android.gms.wearable.*;import com.google.android.gms.tasks.Tasks;import com.daniil.wristlens.core.OriginalTransfer;import com.daniil.wristlens.shared.Wire;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;import java.util.function.*;
class MediaClient implements MessageClient.OnMessageReceivedListener {
 private final Context activity;private final Supplier<String> node;private final Consumer<String> notice;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newFixedThreadPool(2);private final ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();private final Map<String,Request> pending=new HashMap<>();private final Set<ChannelClient.Channel> transfers=ConcurrentHashMap.newKeySet();private volatile int generation;
 private record Request(Consumer<JSONObject> done,Consumer<String> fail){}
 MediaClient(Context a,Supplier<String> n,Consumer<String> msg){activity=a;node=n;notice=msg;OriginalCopies.recover(a);}
 String node(){return node.get();}
 void resume(){Wearable.getMessageClient(activity).addListener(this);}void pause(){Wearable.getMessageClient(activity).removeListener(this);cancelAll();}
 void request(JSONObject j,Consumer<JSONObject> done){request(j,done,notice);}
 void request(JSONObject j,Consumer<JSONObject> done,Consumer<String> fail){String target=node.get();if(target.isEmpty()){fail.accept(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_190));return;}String id=UUID.randomUUID().toString();try{j.put("request",id);}catch(Exception ignored){}pending.put(id,new Request(done,fail));Wearable.getMessageClient(activity).sendMessage(target,Wire.MEDIA,Wire.bytes(j)).addOnFailureListener(e->failure(id,com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_191)));main.postDelayed(()->failure(id,com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_192)),12000);}
 private void failure(String id,String text){Request r=pending.remove(id);if(r!=null)r.fail.accept(text);}
 @Override public void onMessageReceived(MessageEvent event){if(!event.getPath().equals(Wire.MEDIA_RESULT)||!event.getSourceNodeId().equals(node.get()))return;byte[] bytes=event.getData();main.post(()->{try{JSONObject j=Wire.parse(bytes);Request r=pending.remove(j.optString("request"));if(r==null)return;if(j.has("error"))r.fail.accept(com.daniil.wristlens.shared.Strings.message(j.optString("error")));else r.done.accept(j);}catch(Exception e){notice.accept(e.getMessage());}});}
 void launch(String action,String id){request(Wire.object("op","launch","action",action,"id",id),j->remote(j.optString("token")),error->{if(action.equals("start")){notice.accept(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_193));remote("");}else notice.accept(error);});}
 void remote(String ticket){Uri.Builder b=new Uri.Builder().scheme("wristlens").authority("phone");if(!ticket.isEmpty())b.appendQueryParameter("ticket",ticket);Intent intent=new Intent(Intent.ACTION_VIEW,b.build()).addCategory(Intent.CATEGORY_BROWSABLE);var future=new RemoteActivityHelper(activity,io).startRemoteActivity(intent,node.get().isEmpty()?null:node.get());future.addListener(()->{try{future.get();notice.accept(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_194));}catch(Exception e){notice.accept(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_195));}},r->main.post(r));}
 void fetch(String id,boolean save,LongConsumer progress,Consumer<Uri> done,Consumer<String> failed){fetchMeta(id,save,(name,size)->{},progress,done,failed);}
 void fetchMeta(String id,boolean save,BiConsumer<String,Long> metadata,LongConsumer progress,Consumer<Uri> done,Consumer<String> failed){
  CopySettings.Options options=CopySettings.read(activity);int token=generation;JSONObject query=Wire.object("op","file","id",id);if(save){try{query.put("copyProtocol",2).put("photo",options.photo()).put("video",options.video());}catch(JSONException ignored){}}
  request(query,j->{if(token!=generation)return;if(save&&j.optInt("copyProtocol")!=2){failed.accept(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.copy_update_phone));return;}
   String key=copyKey(id,options,j.optString("mime"));if(save){Uri saved=OriginalCopies.find(activity,key);if(saved!=null){done.accept(saved);return;}}
   io.execute(()->receive(j,save,options,key,token,metadata,progress,done,failed));},failed);
 }
 static String copyKey(String id,CopySettings.Options options,String mime){String profile=mime.startsWith("video/")?options.video():options.photo();return options.folder().equals("DCIM/Camera")&&profile.equals("original")?id:"v2:"+id+":"+options.folder()+":"+profile;}
 private void receive(JSONObject j,boolean save,CopySettings.Options options,String key,int token,BiConsumer<String,Long> metadata,LongConsumer progress,Consumer<Uri> done,Consumer<String> failed){
  ChannelClient channels=Wearable.getChannelClient(activity);ChannelClient.Channel ch=null;Uri target=null,staged=null;File cache=null;ScheduledFuture<?> watchdog=null;boolean committed=false;
  try{if(token!=generation)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_196));
   ch=Tasks.await(channels.openChannel(node.get(),Wire.FILE+j.getString("token")),10,TimeUnit.SECONDS);transfers.add(ch);if(token!=generation)throw new IOException("Cancelled");ChannelClient.Channel opened=ch;AtomicLong seen=new AtomicLong(SystemClock.elapsedRealtime());watchdog=timer.scheduleWithFixedDelay(()->{if(SystemClock.elapsedRealtime()-seen.get()>30000)channels.close(opened);},5,5,TimeUnit.SECONDS);
   try(DataInputStream in=new DataInputStream(Tasks.await(channels.getInputStream(ch),10,TimeUnit.SECONDS));DataOutputStream ack=new DataOutputStream(Tasks.await(channels.getOutputStream(ch),10,TimeUnit.SECONDS))){
    String mime=j.getString("mime"),name=j.getString("name");long expected=j.optLong("bytes");
    if(save){com.daniil.wristlens.core.CopyHandshake.Metadata meta=com.daniil.wristlens.core.CopyHandshake.receive(in,j.getString("id"),()->{seen.set(SystemClock.elapsedRealtime());main.post(()->{if(token==generation)progress.accept(-1);});});mime=meta.mime();name=meta.name();expected=meta.bytes();}
    String finalName=name;long finalSize=expected;main.post(()->{if(token==generation)metadata.accept(finalName,finalSize);});
    long available=new StatFs(activity.getFilesDir().getAbsolutePath()).getAvailableBytes()-16*1024*1024;if(expected<=0||expected>available)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_197));
    if(token!=generation)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_196));
    if(save){ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.DISPLAY_NAME,name.replace('/','_').replace('\\','_'));v.put(MediaStore.MediaColumns.MIME_TYPE,mime);v.put(MediaStore.MediaColumns.RELATIVE_PATH,options.folder());v.put(MediaStore.MediaColumns.IS_PENDING,1);target=activity.getContentResolver().insert(mime.startsWith("video/")?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(target==null)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_198));staged=target;OriginalCopies.begin(activity,target);}
    else{cache=File.createTempFile("preview-",mime.startsWith("video/")?".video":".image",activity.getCacheDir());target=Uri.fromFile(cache);}
    try(OutputStream out=save?activity.getContentResolver().openOutputStream(target):new FileOutputStream(cache)){if(out==null)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_119));long received=OriginalTransfer.receive(in,out,available,n->{seen.set(SystemClock.elapsedRealtime());main.post(()->{if(token==generation)progress.accept(n);});});if(received!=expected||token!=generation)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_199));}
    if(save)target=OriginalCopies.commit(activity,key,target);committed=true;try{ack.writeInt(0x4f4b);ack.flush();}catch(IOException ignored){}
   }
   Uri result=target;main.post(()->{if(token==generation)done.accept(result);else if(!save)new File(result.getPath()).delete();});
  }catch(Exception e){String message=e.getMessage()==null?com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_200):e.getMessage();main.post(()->{if(token==generation)failed.accept(com.daniil.wristlens.shared.Strings.message(message));});}
  finally{if(!committed&&target!=null){if(save)try{activity.getContentResolver().delete(target,null,null);}catch(Exception ignored){}else if(cache!=null)cache.delete();}if(staged!=null)OriginalCopies.end(activity,staged);if(watchdog!=null)watchdog.cancel(false);if(ch!=null){channels.close(ch);transfers.remove(ch);}}
 }
 void cancelAll(){generation++;pending.clear();for(ChannelClient.Channel ch:transfers)Wearable.getChannelClient(activity).close(ch);transfers.clear();}
 void close(){pause();io.shutdownNow();timer.shutdownNow();}
}
